import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.Dp3tugkT.js";const u=JSON.parse('{"title":"F1: Collision-Resistant Nanoid Slug Generation","description":"","frontmatter":{},"headers":[],"relativePath":"features/F1-nanoid-slug-generation.md","filePath":"features/F1-nanoid-slug-generation.md"}'),s={name:"features/F1-nanoid-slug-generation.md"};function r(o,e,c,l,h,p){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="f1-collision-resistant-nanoid-slug-generation" tabindex="-1">F1: Collision-Resistant Nanoid Slug Generation <a class="header-anchor" href="#f1-collision-resistant-nanoid-slug-generation" aria-label="Permalink to &quot;F1: Collision-Resistant Nanoid Slug Generation&quot;">​</a></h1><h2 id="_1-description-user-experience" tabindex="-1">1. Description &amp; User Experience <a class="header-anchor" href="#_1-description-user-experience" aria-label="Permalink to &quot;1. Description &amp; User Experience&quot;">​</a></h2><p>Users input a destination URL into the shortening interface (<code>frontend/src/components/ShortenForm.jsx</code>). The system validates the URI structure and issues a compact 7-character slug.</p><h2 id="_2-technical-architecture-permutation-mathematics" tabindex="-1">2. Technical Architecture &amp; Permutation Mathematics <a class="header-anchor" href="#_2-technical-architecture-permutation-mathematics" aria-label="Permalink to &quot;2. Technical Architecture &amp; Permutation Mathematics&quot;">​</a></h2><p>Using a 64-character URL-safe alphabet (<code>A-Za-z0-9_-</code>) across 7 characters yields: $$64^7 = 4,398,046,511,104 \\text{ unique IDs}$$ Even at an aggressive generation rate of 1,000 URLs per second, it would take decades before encountering a 1% probability of collision.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    LongURL[Destination Long URL] --&gt; Valid[URI Syntax Validation]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Valid --&gt; Service[short_url.service.js]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Service --&gt; NanoIDGen[nanoid 7-Char Generation]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    NanoIDGen --&gt; DBCheck[MongoDB Insert with Unique Index]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DBCheck --&gt;|Success| ReturnSlug[Return Short URL]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DBCheck --&gt;|Duplicate 11000 Error| Retry[Generate New Slug &amp; Retry]</span></span></code></pre></div><h2 id="_3-say-it-out-loud" tabindex="-1">3. Say It Out Loud <a class="header-anchor" href="#_3-say-it-out-loud" aria-label="Permalink to &quot;3. Say It Out Loud&quot;">​</a></h2><p>&quot;I implemented the core link shortening engine using Nanoid with a customized 7-character alphabet. With 64 possible characters per slot, this provides over 4.3 trillion unique combinations, making collision probability virtually zero for standard web scale. I chose Nanoid over MD5 or SHA-256 truncation because cryptographic hashes are prone to collision when truncated to 7 characters and contain non-URL-safe characters. If a collision ever occurs, the MongoDB unique index triggers a duplicate key error, which the service catches to automatically regenerate a fresh slug.&quot;</p>`,8)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
